export { MenuPage, type MenuPageProps } from "@/components/plugins/menus/public";
export {
  MenuItemsPage,
  MenuItemEditorPage,
  MenuTaxonomyPage,
  type MenuItemsPageProps,
  type MenuItemEditorPageProps,
  type MenuTaxonomyPageProps,
} from "@/components/plugins/menus/admin";
export { menusLabels, type MenusLabels } from "@/components/plugins/menus/labels";
export { MenuSpiceBadge, type MenuSpiceBadgeProps } from "@/components/plugins/menus/spice-badge";
export { MenuLabelBadge, type MenuLabelBadgeProps } from "@/components/plugins/menus/label-badge";
export {
  menuLabelPresets,
  getMenuLabelPreset,
  getMenuFilterLabels,
  type MenuLabelPreset,
  type MenuLabelTone,
  type MenuLabelIcon,
} from "@/components/plugins/menus/label-presets";
export { MenuError, buildMenu, type MenuErrorCode } from "@/components/plugins/menus/model";
export type * from "@/components/plugins/menus/types";

export interface MenuTranslation {
  name: string;
  description: string;
}

export interface MenuCategory {
  id: string;
  position: number;
  translations: Record<string, string>;
}

export interface MenuLabel {
  id: string;
  kind: "allergen" | "dietary";
  position: number;
  translations: Record<string, string>;
}

export type MenuSpiceLevel = 0 | 1 | 2 | 3;

export interface MenuItemSize {
  id: string;
  priceMinor: number;
  translations: Record<string, string>;
}

export interface MenuItem {
  id: string;
  version: number;
  categoryId: string;
  priceMinor: number;
  sizes?: MenuItemSize[];
  position: number;
  visible: boolean;
  soldOut: boolean;
  spiceLevel?: MenuSpiceLevel;
  imageEntryId: string | null;
  labelIds: string[];
  translations: Record<string, MenuTranslation>;
}

export type MenuItemInput = Omit<MenuItem, "id" | "version">;
export type MenuCategoryInput = Omit<MenuCategory, "id">;
export type MenuLabelInput = Omit<MenuLabel, "id">;

export interface MenuViewLabel {
  id: string;
  kind: MenuLabel["kind"];
  name: string;
}

export interface MenuViewItem extends Omit<MenuItem, "translations" | "labelIds" | "sizes"> {
  name: string;
  description: string;
  labels: MenuViewLabel[];
  sizes?: { id: string; name: string; priceMinor: number }[];
}
export interface MenuViewCategory {
  id: string;
  name: string;
  items: MenuViewItem[];
}

/** The host implements transport. Staff identity is supplied only by its server session. */
export interface MenusClient {
  list(): Promise<MenuItem[]>;
  get(id: string): Promise<MenuItem>;
  create(input: MenuItemInput): Promise<MenuItem>;
  save(id: string, version: number, input: MenuItemInput): Promise<MenuItem>;
  remove(id: string): Promise<void>;
  categories(): Promise<MenuCategory[]>;
  saveCategory(input: MenuCategoryInput & { id?: string }): Promise<MenuCategory>;
  removeCategory(id: string): Promise<void>;
  labels(): Promise<MenuLabel[]>;
  saveLabel(input: MenuLabelInput & { id?: string }): Promise<MenuLabel>;
  removeLabel(id: string): Promise<void>;
}

import type {
  MenuCategory,
  MenuCategoryInput,
  MenuItem,
  MenuItemInput,
  MenuLabel,
  MenuLabelInput,
  MenuSpiceLevel,
  MenuTranslation,
  MenuViewCategory,
} from "@/components/plugins/menus/types";

export type MenuErrorCode =
  | "INVALID"
  | "NOT_FOUND"
  | "FORBIDDEN"
  | "CONFLICT"
  | "IN_USE"
  | "STORAGE";
export class MenuError extends Error {
  readonly code: MenuErrorCode;
  constructor(code: MenuErrorCode) {
    super(code);
    this.name = "MenuError";
    this.code = code;
  }
}

const fail = (condition: unknown) => {
  if (!condition) throw new MenuError("INVALID");
};
const position = (value: number) => fail(Number.isSafeInteger(value) && value >= 0);
const validPrice = (value: number) =>
  fail(Number.isSafeInteger(value) && value >= 0 && value <= 1e9);

export function validateTranslations(
  input: Record<string, string | MenuTranslation>,
  baseLocale: string,
  withDescription: boolean,
) {
  fail(input && typeof input === "object" && !Array.isArray(input));
  const result: Record<string, string | MenuTranslation> = {};
  for (const [locale, value] of Object.entries(input)) {
    fail(/^[a-z]{2,3}(?:-[A-Za-z0-9]+)*$/.test(locale));
    if (withDescription) {
      fail(value && typeof value === "object" && !Array.isArray(value));
      const translation = value as MenuTranslation;
      fail(typeof translation.name === "string" && typeof translation.description === "string");
      fail(translation.name.trim().length <= 200 && translation.description.trim().length <= 2000);
      result[locale] = {
        name: translation.name.trim(),
        description: translation.description.trim(),
      };
    } else {
      fail(typeof value === "string" && value.trim().length <= 120);
      result[locale] = (value as string).trim();
    }
  }
  const base = result[baseLocale];
  fail(withDescription ? !!(base as MenuTranslation | undefined)?.name : !!base);
  return result;
}

export function validateItem(input: MenuItemInput, baseLocale: string) {
  fail(input && typeof input === "object");
  fail(typeof input.categoryId === "string" && !!input.categoryId);
  validPrice(input.priceMinor);
  const sizes = input.sizes === undefined ? [] : input.sizes;
  fail(Array.isArray(sizes) && sizes.length <= 20);
  const validatedSizes = sizes.map((size) => {
    fail(size && typeof size === "object" && !Array.isArray(size));
    fail(typeof size.id === "string" && !!size.id.trim() && size.id.length <= 120);
    validPrice(size.priceMinor);
    return {
      id: size.id,
      priceMinor: size.priceMinor,
      translations: validateTranslations(size.translations, baseLocale, false) as Record<
        string,
        string
      >,
    };
  });
  fail(new Set(validatedSizes.map((size) => size.id)).size === validatedSizes.length);
  position(input.position);
  fail(typeof input.visible === "boolean" && typeof input.soldOut === "boolean");
  const spiceLevel = input.spiceLevel === undefined ? 0 : input.spiceLevel;
  fail(Number.isInteger(spiceLevel) && spiceLevel >= 0 && spiceLevel <= 3);
  fail(input.imageEntryId === null || typeof input.imageEntryId === "string");
  fail(Array.isArray(input.labelIds) && input.labelIds.length <= 40);
  fail(input.labelIds.every((id) => typeof id === "string" && !!id));
  fail(new Set(input.labelIds).size === input.labelIds.length);
  return {
    ...input,
    priceMinor: validatedSizes[0]?.priceMinor ?? input.priceMinor,
    sizes: validatedSizes,
    spiceLevel: spiceLevel as MenuSpiceLevel,
    translations: validateTranslations(input.translations, baseLocale, true) as Record<
      string,
      MenuTranslation
    >,
  };
}

export function validateCategory(input: MenuCategoryInput, baseLocale: string) {
  position(input.position);
  return {
    position: input.position,
    translations: validateTranslations(input.translations, baseLocale, false) as Record<
      string,
      string
    >,
  };
}

export function validateLabel(input: MenuLabelInput, baseLocale: string) {
  fail(input.kind === "allergen" || input.kind === "dietary");
  position(input.position);
  return {
    kind: input.kind,
    position: input.position,
    translations: validateTranslations(input.translations, baseLocale, false) as Record<
      string,
      string
    >,
  };
}

export function localized<T>(translations: Record<string, T>, locale: string, baseLocale: string) {
  const value = translations[locale];
  if (typeof value === "string") return (value.trim() ? value : translations[baseLocale]) as T;
  if (value && typeof value === "object" && "name" in value && typeof value.name === "string")
    return (value.name.trim() ? value : translations[baseLocale]) as T;
  return value || translations[baseLocale];
}

export function parsePrice(input: string, fractionDigits: number) {
  fail(Number.isInteger(fractionDigits) && fractionDigits >= 0 && fractionDigits <= 3);
  fail(
    new RegExp(fractionDigits ? `^\\d+(?:\\.\\d{1,${fractionDigits}})?$` : "^\\d+$").test(input),
  );
  const [whole, fraction = ""] = input.split(".");
  const amount =
    Number(whole) * 10 ** fractionDigits + Number(fraction.padEnd(fractionDigits, "0"));
  fail(Number.isSafeInteger(amount) && amount <= 1e9);
  return amount;
}

export function buildMenu(
  items: readonly MenuItem[],
  categories: readonly MenuCategory[],
  labels: readonly MenuLabel[],
  locale: string,
  baseLocale: string,
): MenuViewCategory[] {
  const labelsById = new Map(labels.map((label) => [label.id, label]));
  return [...categories]
    .sort((a, b) => a.position - b.position || a.id.localeCompare(b.id))
    .map((category) => ({
      id: category.id,
      name: localized(category.translations, locale, baseLocale),
      items: items
        .filter((item) => item.visible && item.categoryId === category.id)
        .sort((a, b) => a.position - b.position || a.id.localeCompare(b.id))
        .map((item) => {
          const translation = localized(item.translations, locale, baseLocale);
          return {
            id: item.id,
            version: item.version,
            categoryId: item.categoryId,
            priceMinor: item.priceMinor,
            sizes: (item.sizes ?? []).map((size) => ({
              id: size.id,
              priceMinor: size.priceMinor,
              name: localized(size.translations, locale, baseLocale),
            })),
            position: item.position,
            visible: item.visible,
            soldOut: item.soldOut,
            spiceLevel: item.spiceLevel ?? 0,
            imageEntryId: item.imageEntryId,
            name: translation.name,
            description: translation.description,
            labels: item.labelIds.flatMap((id) => {
              const label = labelsById.get(id);
              return label
                ? [
                    {
                      id,
                      kind: label.kind,
                      name: localized(label.translations, locale, baseLocale),
                    },
                  ]
                : [];
            }),
          };
        }),
    }))
    .filter((category) => category.items.length > 0);
}

