"use client";

import { LeafIcon, TriangleAlertIcon } from "lucide-react";
import { useEffect, useId, useRef, useState, type ComponentType } from "react";

import { Image, type ImageProps } from "@/components/image";
import { Link } from "@/components/link";
import { MenuLabelBadge, menuLabelColorClasses } from "@/components/plugins/menus/label-badge";
import { getMenuFilterLabels } from "@/components/plugins/menus/label-presets";
import { menusLabels, type MenusLabels } from "@/components/plugins/menus/labels";
import { MenuSpiceBadge } from "@/components/plugins/menus/spice-badge";
import type { MenuViewCategory, MenuViewLabel } from "@/components/plugins/menus/types";
import { cn } from "@/components/utils/cn";

export interface MenuPageProps {
  sections: readonly MenuViewCategory[];
  locale: string;
  currency: string;
  filterLabels?: readonly MenuViewLabel[];
  imageUrl?: (itemId: string) => string;
  imageComponent?: ComponentType<ImageProps>;
  labels?: Partial<MenusLabels>;
  className?: string;
}

export function MenuPage({
  sections,
  locale,
  currency,
  filterLabels,
  imageUrl,
  imageComponent: MenuImage = Image,
  labels: overrides,
  className,
}: MenuPageProps) {
  const labels = { ...menusLabels, ...overrides };
  const id = `factory-menu-filters-${useId()}`;
  const navigationRef = useRef<HTMLElement>(null);
  const [activeCategory, setActiveCategory] = useState<string>();
  const [selectedSizes, setSelectedSizes] = useState<Record<string, string>>({});
  const [selected, setSelected] = useState<{ allergen: string[]; dietary: string[] }>({
    allergen: [],
    dietary: [],
  });
  const options = sections.length ? getMenuFilterLabels(sections, locale, filterLabels) : [];
  const allergens = selected.allergen.filter((id) => options.some((label) => label.id === id));
  const dietary = selected.dietary.filter((id) => options.some((label) => label.id === id));
  const hasFilters = allergens.length > 0 || dietary.length > 0;
  const filteredSections = sections
    .map((section) => ({
      ...section,
      items: section.items.filter(
        (item) =>
          !item.labels.some((label) => label.kind === "allergen" && allergens.includes(label.id)) &&
          dietary.every((id) =>
            item.labels.some((label) => label.kind === "dietary" && label.id === id),
          ),
      ),
    }))
    .filter((section) => section.items.length > 0);
  const count = filteredSections.reduce((total, section) => total + section.items.length, 0);
  const categoryIds = filteredSections.map((section) => section.id).join(",");
  useEffect(() => {
    const navigation = navigationRef.current;
    if (!navigation) return;
    const links = [...navigation.querySelectorAll<HTMLAnchorElement>("a")];
    const categories = links.flatMap((link) => {
      const section = document.getElementById(decodeURIComponent(link.hash.slice(1)));
      return section ? [{ link, section }] : [];
    });
    let frame = 0;
    let currentSection: string | undefined;
    const update = () => {
      const threshold = navigation.getBoundingClientRect().bottom + 16;
      const current =
        categories.findLast(({ section }) => section.getBoundingClientRect().top <= threshold) ??
        categories[0];
      if (!current) return;
      const atBottom =
        window.scrollY > 0 &&
        window.scrollY + window.innerHeight >= document.documentElement.scrollHeight - 2;
      const { link, section } = atBottom ? categories[categories.length - 1] : current;
      if (section.id === currentSection) return;
      currentSection = section.id;
      setActiveCategory(section.id);
      if (
        link.offsetLeft < navigation.scrollLeft ||
        link.offsetLeft + link.offsetWidth > navigation.scrollLeft + navigation.clientWidth
      ) {
        navigation.scrollTo({
          left: link.offsetLeft - (navigation.clientWidth - link.offsetWidth) / 2,
        });
      }
    };
    const schedule = (event: Event) => {
      if (event.target === navigation) return;
      cancelAnimationFrame(frame);
      frame = requestAnimationFrame(update);
    };
    update();
    document.addEventListener("scroll", schedule, true);
    window.addEventListener("resize", schedule);
    return () => {
      cancelAnimationFrame(frame);
      document.removeEventListener("scroll", schedule, true);
      window.removeEventListener("resize", schedule);
    };
  }, [categoryIds]);
  const formatter = new Intl.NumberFormat(locale, { style: "currency", currency });
  const divisor = 10 ** (formatter.resolvedOptions().maximumFractionDigits ?? 2);
  return (
    <section
      className={cn(
        "mx-auto w-full max-w-6xl space-y-10 px-4 py-10 text-foreground sm:px-6",
        className,
      )}
    >
      <header>
        <h1 className="font-serif text-4xl font-semibold">{labels.menu}</h1>
      </header>
      {filteredSections.length ? (
        <nav
          ref={navigationRef}
          aria-label={labels.categories}
          className="sticky top-[var(--menu-top-offset,0px)] z-10 flex gap-2 overflow-x-auto border-b border-border bg-background py-2 print:hidden"
        >
          {filteredSections.map((section, index) => {
            const sectionId = `${id}-category-${section.id}`;
            const active = activeCategory ? activeCategory === sectionId : index === 0;
            return (
              <Link
                key={section.id}
                href={`#${sectionId}`}
                aria-current={active ? "location" : undefined}
                className={cn(
                  "inline-flex min-h-10 shrink-0 cursor-pointer items-center rounded-lg px-4 py-2 text-sm font-medium whitespace-nowrap outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-inset",
                  active
                    ? "bg-primary text-primary-foreground"
                    : "text-muted-foreground hover:bg-accent hover:text-accent-foreground",
                )}
              >
                {section.name}
              </Link>
            );
          })}
        </nav>
      ) : null}
      {options.length ? (
        <div className="space-y-4 rounded-2xl border border-border bg-card p-5 text-card-foreground">
          <div className="grid gap-5 sm:grid-cols-2">
            {(["allergen", "dietary"] as const).map((kind) => {
              const tags = options.filter((label) => label.kind === kind);
              const Icon = kind === "allergen" ? TriangleAlertIcon : LeafIcon;
              return tags.length ? (
                <fieldset
                  key={kind}
                  className="min-w-0 space-y-3"
                  aria-describedby={`${id}-${kind}`}
                >
                  <legend className="flex items-center gap-2 font-semibold">
                    <Icon aria-hidden="true" className="size-4 shrink-0" />
                    {kind === "allergen" ? labels.excludeAllergens : labels.dietary}
                  </legend>
                  <p id={`${id}-${kind}`} className="text-sm text-muted-foreground">
                    {kind === "allergen" ? labels.allergenFilterHelp : labels.dietaryFilterHelp}
                  </p>
                  <div className="flex flex-wrap gap-2">
                    {tags.map((tag) => {
                      const checked = selected[kind].includes(tag.id);
                      return (
                        <label
                          key={tag.id}
                          className={cn(
                            "inline-flex min-h-10 max-w-full cursor-pointer items-center gap-2 rounded-full border border-transparent px-3 py-2 text-sm",
                            menuLabelColorClasses(tag),
                            checked && "ring-2 ring-ring ring-offset-2 ring-offset-background",
                          )}
                        >
                          <input
                            type="checkbox"
                            checked={checked}
                            className="size-4 shrink-0 cursor-pointer accent-primary focus-visible:ring-2 focus-visible:ring-ring"
                            onChange={(event) => {
                              const checked = event.target.checked;
                              setSelected((current) => ({
                                ...current,
                                [kind]: checked
                                  ? [...current[kind], tag.id]
                                  : current[kind].filter((id) => id !== tag.id),
                              }));
                            }}
                          />
                          <MenuLabelBadge label={tag} className="px-0 py-0 text-sm" />
                        </label>
                      );
                    })}
                  </div>
                </fieldset>
              ) : null;
            })}
          </div>
          <div className="flex flex-wrap items-center justify-between gap-2">
            <output className="text-sm text-muted-foreground" aria-live="polite">
              {hasFilters && count === 0
                ? labels.noFilterMatches
                : `${labels.matchingItems}: ${count}`}
            </output>
            <button
              type="button"
              disabled={!hasFilters}
              className="inline-flex min-h-9 cursor-pointer items-center justify-center rounded-lg border border-border px-3 text-sm font-medium outline-none hover:bg-accent hover:text-accent-foreground focus-visible:ring-2 focus-visible:ring-ring disabled:cursor-not-allowed disabled:opacity-50"
              onClick={() => setSelected({ allergen: [], dietary: [] })}
            >
              {labels.clearFilters}
            </button>
          </div>
        </div>
      ) : null}
      {sections.length === 0 ? <p className="text-muted-foreground">{labels.emptyMenu}</p> : null}
      {filteredSections.map((section) => (
        <section
          key={section.id}
          id={`${id}-category-${section.id}`}
          tabIndex={-1}
          className="scroll-mt-[calc(var(--menu-top-offset,0px)+4.5rem)] space-y-5 rounded-lg focus-visible:outline-2 focus-visible:outline-ring"
          aria-label={section.name}
        >
          <h2 className="border-b border-border pb-3 font-serif text-2xl font-semibold">
            {section.name}
          </h2>
          <div className="grid gap-5 md:grid-cols-2">
            {section.items.map((item) => {
              const sizes = item.sizes ?? [];
              const selectedSize =
                sizes.find((size) => size.id === selectedSizes[item.id]) ?? sizes[0];
              return (
                <article
                  key={item.id}
                  className="overflow-hidden rounded-2xl border border-border bg-card text-card-foreground"
                >
                  {item.imageEntryId && imageUrl ? (
                    <MenuImage
                      src={imageUrl(item.id)}
                      alt={item.name}
                      className="aspect-[16/9] w-full object-cover"
                    />
                  ) : null}
                  <div className="space-y-3 p-5">
                    <div className="flex flex-wrap items-start justify-between gap-3">
                      <h3 className="min-w-0 flex-1 text-lg font-semibold wrap-anywhere">
                        {item.name}
                      </h3>
                      <div className="ml-auto flex max-w-full flex-col items-end gap-2">
                        {item.soldOut ? (
                          <span className="rounded-full bg-status-pending px-2.5 py-1 text-xs font-medium text-status-pending-foreground">
                            {labels.soldOut}
                          </span>
                        ) : null}
                        <output
                          aria-label={labels.price}
                          aria-live="polite"
                          className="font-semibold"
                        >
                          {formatter.format(
                            (selectedSize?.priceMinor ?? item.priceMinor) / divisor,
                          )}
                        </output>
                      </div>
                    </div>
                    {item.description ? (
                      <p className="text-sm text-muted-foreground">{item.description}</p>
                    ) : null}
                    {sizes.length ? (
                      <fieldset className="min-w-0 space-y-2">
                        <legend className="text-sm font-medium">{labels.sizes}</legend>
                        <div className="flex flex-wrap gap-2">
                          {sizes.map((size) => {
                            const checked = selectedSize?.id === size.id;
                            return (
                              <label
                                key={size.id}
                                className={cn(
                                  "inline-flex min-h-11 max-w-full cursor-pointer items-center gap-2 rounded-full border px-3 py-2 text-sm focus-within:ring-2 focus-within:ring-ring focus-within:ring-offset-2 focus-within:ring-offset-background",
                                  checked
                                    ? "border-primary bg-primary text-primary-foreground"
                                    : "border-border hover:bg-accent hover:text-accent-foreground",
                                )}
                              >
                                <input
                                  type="radio"
                                  name={`${id}-size-${item.id}`}
                                  value={size.id}
                                  checked={checked}
                                  className="sr-only"
                                  onChange={() =>
                                    setSelectedSizes((current) => ({
                                      ...current,
                                      [item.id]: size.id,
                                    }))
                                  }
                                />
                                <span className="wrap-anywhere">{size.name}</span>
                                <span className="shrink-0 font-semibold">
                                  {formatter.format(size.priceMinor / divisor)}
                                </span>
                              </label>
                            );
                          })}
                        </div>
                      </fieldset>
                    ) : null}
                    {(item.spiceLevel ?? 0) > 0 || item.labels.length ? (
                      <div className="flex flex-wrap items-center gap-2">
                        <MenuSpiceBadge level={item.spiceLevel ?? 0} labels={labels} />
                        {(["allergen", "dietary"] as const).map((kind) => {
                          const tags = item.labels.filter((label) => label.kind === kind);
                          return tags.length ? (
                            <ul
                              key={kind}
                              aria-label={kind === "allergen" ? labels.allergens : labels.dietary}
                              className="contents"
                            >
                              {tags.map((tag) => (
                                <li key={tag.id} className="inline-flex max-w-full">
                                  <MenuLabelBadge label={tag} />
                                </li>
                              ))}
                            </ul>
                          ) : null;
                        })}
                      </div>
                    ) : null}
                  </div>
                </article>
              );
            })}
          </div>
        </section>
      ))}
    </section>
  );
}

"use client";

import { Dialog } from "@base-ui/react/dialog";
import { Tabs } from "@base-ui/react/tabs";
import { PencilIcon, PlusIcon, RefreshCwIcon, SettingsIcon, Trash2Icon } from "lucide-react";
import { useEffect, useRef, useState, type ComponentType } from "react";

import { Link, type LinkProps } from "@/components/link";
import { DriveBrowser, type DriveClient, type DriveEntry } from "@/components/plugins/drive";
import type { DriveTransfer } from "@/components/plugins/drive/transfer";
import { MenuLabelBadge } from "@/components/plugins/menus/label-badge";
import { menusLabels, type MenusLabels } from "@/components/plugins/menus/labels";
import { parsePrice } from "@/components/plugins/menus/model";
import { MenuSpiceBadge } from "@/components/plugins/menus/spice-badge";
import type {
  MenuCategory,
  MenuItem,
  MenuItemInput,
  MenuLabel,
  MenusClient,
} from "@/components/plugins/menus/types";
import { matchesTableSearch, TableSearch } from "@/components/table-search";
import { cn } from "@/components/utils/cn";
import {
  tableActionCellClass,
  tableCellClass,
  tableClass,
  tableHeaderClass,
  tablePanelClass,
  tableRowClass,
} from "@/components/utils/table-styles";

const field =
  "w-full rounded-xl border border-input bg-background px-3 py-2 text-foreground focus-visible:outline-2 focus-visible:outline-ring";
const button =
  "inline-flex min-h-9 items-center justify-center gap-2 rounded-lg px-3 text-sm font-medium text-foreground outline-none hover:bg-accent hover:text-accent-foreground focus-visible:ring-2 focus-visible:ring-ring disabled:pointer-events-none disabled:opacity-50 [&_svg]:size-4 cursor-pointer disabled:cursor-not-allowed aria-disabled:cursor-not-allowed data-disabled:cursor-not-allowed";
const outlineButton = cn(button, "border border-border");
const primary = cn(
  button,
  "bg-primary text-primary-foreground hover:bg-primary/90 hover:text-primary-foreground",
);
const page = "mx-auto w-full max-w-5xl space-y-6 px-4 py-8 text-foreground";
const iconButton = cn(button, "size-8 min-h-8 shrink-0 p-0");
const editorLocales = (locales: readonly { code: string; name: string }[], baseLocale: string) =>
  locales.some((locale) => locale.code === baseLocale)
    ? locales
    : [{ code: baseLocale, name: baseLocale }, ...locales];

function ErrorMessage({ message }: { message?: string }) {
  return message ? (
    <p role="alert" className="text-sm text-destructive">
      {message}
    </p>
  ) : null;
}

function DeleteControl({
  label,
  confirm,
  cancel,
  errorMessage,
  onDelete,
  onDone,
}: {
  label: string;
  confirm: string;
  cancel: string;
  errorMessage: string;
  onDelete: () => Promise<void>;
  onDone: () => void;
}) {
  const [open, setOpen] = useState(false);
  const [pending, setPending] = useState(false);
  const [error, setError] = useState(false);
  const lock = useRef(false);
  return (
    <Dialog.Root open={open} onOpenChange={(value) => !pending && setOpen(value)}>
      <Dialog.Trigger
        className={cn(iconButton, "text-destructive hover:text-destructive")}
        aria-label={label}
      >
        <Trash2Icon aria-hidden="true" className="size-4 shrink-0" />
      </Dialog.Trigger>
      <Dialog.Portal>
        <Dialog.Backdrop className="fixed inset-0 z-50 bg-foreground/30" />
        <Dialog.Popup className="fixed top-1/2 left-1/2 z-50 w-[min(26rem,calc(100vw-2rem))] -translate-x-1/2 -translate-y-1/2 space-y-5 rounded-2xl border border-border bg-popover p-6 text-popover-foreground shadow-xl">
          <Dialog.Title className="text-lg font-semibold">{label}</Dialog.Title>
          <Dialog.Description className="text-sm text-muted-foreground">
            {confirm}?
          </Dialog.Description>
          {error ? <ErrorMessage message={errorMessage} /> : null}
          <div className="flex flex-wrap justify-end gap-2">
            <Dialog.Close className={outlineButton} disabled={pending}>
              {cancel}
            </Dialog.Close>
            <button
              type="button"
              className={cn(
                primary,
                "bg-destructive text-destructive-foreground hover:bg-destructive/90 hover:text-destructive-foreground",
              )}
              disabled={pending}
              onClick={() => {
                if (lock.current) return;
                lock.current = true;
                setPending(true);
                setError(false);
                void onDelete()
                  .then(() => {
                    setOpen(false);
                    onDone();
                  })
                  .catch(() => setError(true))
                  .finally(() => {
                    lock.current = false;
                    setPending(false);
                  });
              }}
            >
              {confirm}
            </button>
          </div>
        </Dialog.Popup>
      </Dialog.Portal>
    </Dialog.Root>
  );
}

export interface MenuItemsPageProps {
  client: MenusClient;
  baseLocale: string;
  newHref: string;
  taxonomyHref: string;
  getEditHref: (item: MenuItem) => string;
  linkComponent?: ComponentType<LinkProps>;
  labels?: Partial<MenusLabels>;
  className?: string;
}

export function MenuItemsPage({
  client,
  baseLocale,
  newHref,
  taxonomyHref,
  getEditHref,
  linkComponent: HostLink = Link,
  labels: overrides,
  className,
}: MenuItemsPageProps) {
  const labels = { ...menusLabels, ...overrides };
  const [search, setSearch] = useState("");
  const [revision, setRevision] = useState(0);
  const [data, setData] = useState<{ items: MenuItem[]; categories: MenuCategory[] }>();
  const [error, setError] = useState(false);
  useEffect(() => {
    let active = true;
    Promise.all([client.list(), client.categories()])
      .then(([items, categories]) => {
        if (active) {
          setData({ items, categories });
          setError(false);
        }
      })
      .catch(() => {
        if (active) setError(true);
      });
    return () => {
      active = false;
    };
  }, [client, revision]);
  const categoryNames = new Map(
    data?.categories.map((category) => [category.id, category.translations[baseLocale]]) ?? [],
  );
  const filteredItems =
    data?.items.filter((item) =>
      matchesTableSearch(
        search,
        item.translations[baseLocale]?.name,
        categoryNames.get(item.categoryId),
        item.visible ? labels.yes : labels.no,
        item.soldOut ? labels.yes : labels.no,
      ),
    ) ?? [];
  return (
    <section className={cn(page, className)}>
      <div className={tablePanelClass}>
        <header className="flex flex-wrap items-center justify-between gap-3">
          <h1 className="text-base font-semibold">{labels.items}</h1>
          <div className="ml-auto flex flex-wrap items-center justify-end gap-2">
            <HostLink href={taxonomyHref} className={outlineButton}>
              <SettingsIcon className="size-4 shrink-0" aria-hidden="true" />
              {labels.categories} / {labels.labels}
            </HostLink>
            <TableSearch
              value={search}
              onValueChange={setSearch}
              label={labels.search}
              clearLabel={labels.clearSearch}
            />
            <HostLink href={newHref} className={primary}>
              <PlusIcon aria-hidden="true" className="size-4 shrink-0" />
              {labels.newItem}
            </HostLink>
          </div>
        </header>
        {error ? (
          <div>
            <ErrorMessage message={labels.error} />
            <button className={button} onClick={() => setRevision((n) => n + 1)}>
              <RefreshCwIcon className="size-4 shrink-0" aria-hidden="true" />
              {labels.retry}
            </button>
          </div>
        ) : null}
        {!data && !error ? <output>{labels.loading}</output> : null}
        {data?.items.length === 0 ? <p>{labels.emptyItems}</p> : null}
        {data?.items.length ? (
          <div className="mt-5 overflow-x-auto">
            <table className={tableClass}>
              <thead>
                <tr className={tableRowClass}>
                  <th scope="col" className={tableHeaderClass}>
                    {labels.name}
                  </th>
                  <th scope="col" className={tableHeaderClass}>
                    {labels.category}
                  </th>
                  <th scope="col" className={tableHeaderClass}>
                    {labels.visible}
                  </th>
                  <th scope="col" className={tableHeaderClass}>
                    {labels.unavailable}
                  </th>
                  <th scope="col" className={tableActionCellClass}>
                    {labels.editItem}
                  </th>
                </tr>
              </thead>
              <tbody className="[&_tr:last-child]:border-0">
                {filteredItems.map((item) => (
                  <tr key={item.id} className={tableRowClass}>
                    <td className={cn(tableCellClass, "font-medium")}>
                      {item.translations[baseLocale]?.name}
                    </td>
                    <td className={tableCellClass}>{categoryNames.get(item.categoryId)}</td>
                    <td className={tableCellClass}>
                      <span
                        className={cn(
                          "inline-flex rounded-full px-2.5 py-1 text-xs font-medium",
                          item.visible
                            ? "bg-status-success text-status-success-foreground"
                            : "bg-status-not-started text-status-not-started-foreground",
                        )}
                      >
                        {item.visible ? labels.yes : labels.no}
                      </span>
                    </td>
                    <td className={tableCellClass}>
                      <span
                        className={cn(
                          "inline-flex rounded-full px-2.5 py-1 text-xs font-medium",
                          item.soldOut
                            ? "bg-status-pending text-status-pending-foreground"
                            : "bg-status-success text-status-success-foreground",
                        )}
                      >
                        {item.soldOut ? labels.yes : labels.no}
                      </span>
                    </td>
                    <td className={tableActionCellClass}>
                      <div className="flex flex-wrap justify-end gap-2">
                        <HostLink
                          href={getEditHref(item)}
                          className={iconButton}
                          aria-label={`${labels.editItem}: ${item.translations[baseLocale]?.name}`}
                        >
                          <PencilIcon aria-hidden="true" className="size-4 shrink-0" />
                        </HostLink>
                        <DeleteControl
                          label={`${labels.deleteItem}: ${item.translations[baseLocale]?.name}`}
                          confirm={labels.confirmDelete}
                          cancel={labels.cancel}
                          errorMessage={labels.deleteFilesFirst}
                          onDelete={() => client.remove(item.id)}
                          onDone={() => setRevision((n) => n + 1)}
                        />
                      </div>
                    </td>
                  </tr>
                ))}
                {filteredItems.length === 0 && (
                  <tr className={tableRowClass}>
                    <td colSpan={5} className={tableCellClass}>
                      {labels.noMatches}
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        ) : null}
      </div>
    </section>
  );
}

export interface MenuItemEditorPageProps {
  client: MenusClient;
  item?: MenuItem;
  categories: readonly MenuCategory[];
  labelsData: readonly MenuLabel[];
  locales: readonly { code: string; name: string }[];
  baseLocale: string;
  currency: string;
  backHref: string;
  onSaved: (item: MenuItem) => void;
  driveClient?: DriveClient;
  driveTransfer?: DriveTransfer;
  photoFolderId?: string | null;
  getFolderHref?: (folderId: string | null) => string;
  linkComponent?: ComponentType<LinkProps>;
  labels?: Partial<MenusLabels>;
  className?: string;
}

export function MenuItemEditorPage({
  client,
  item,
  categories,
  labelsData,
  locales,
  baseLocale,
  currency,
  backHref,
  onSaved,
  driveClient,
  driveTransfer,
  photoFolderId,
  getFolderHref,
  linkComponent: HostLink = Link,
  labels: overrides,
  className,
}: MenuItemEditorPageProps) {
  const labels = { ...menusLabels, ...overrides };
  const [draft, setDraft] = useState<MenuItemInput>(() =>
    item
      ? {
          categoryId: item.categoryId,
          priceMinor: item.priceMinor,
          position: item.position,
          visible: item.visible,
          soldOut: item.soldOut,
          spiceLevel: item.spiceLevel ?? 0,
          imageEntryId: item.imageEntryId,
          labelIds: [...item.labelIds],
          translations: { ...item.translations },
        }
      : {
          categoryId: categories[0]?.id ?? "",
          priceMinor: 0,
          position: 0,
          visible: false,
          soldOut: false,
          spiceLevel: 0,
          imageEntryId: null,
          labelIds: [],
          translations: { [baseLocale]: { name: "", description: "" } },
        },
  );
  const [selectedLocale, setSelectedLocale] = useState(baseLocale);
  const [pending, setPending] = useState(false);
  const [feedback, setFeedback] = useState<{ error: boolean; text: string }>();
  const [photoName, setPhotoName] = useState("");
  const [savedVersion, setSavedVersion] = useState(item?.version);
  const lock = useRef(false);
  const formatter = new Intl.NumberFormat(baseLocale, { style: "currency", currency });
  const digits = formatter.resolvedOptions().maximumFractionDigits ?? 2;
  const [price, setPrice] = useState((draft.priceMinor / 10 ** digits).toFixed(digits));
  const [sizes, setSizes] = useState(() =>
    (item?.sizes ?? []).map((size) => ({
      id: size.id,
      price: (size.priceMinor / 10 ** digits).toFixed(digits),
      translations: { ...size.translations },
    })),
  );
  const updateTranslation = (locale: string, patch: Partial<MenuItem["translations"][string]>) =>
    setDraft((current) => ({
      ...current,
      translations: {
        ...current.translations,
        [locale]: { ...(current.translations[locale] ?? { name: "", description: "" }), ...patch },
      },
    }));
  async function submit() {
    if (lock.current) return;
    lock.current = true;
    setPending(true);
    setFeedback(undefined);
    try {
      if (!draft.translations[baseLocale]?.name.trim()) {
        setSelectedLocale(baseLocale);
        setFeedback({ error: true, text: labels.baseNameRequired });
        return;
      }
      if (sizes.some((size) => !size.translations[baseLocale]?.trim())) {
        setSelectedLocale(baseLocale);
        setFeedback({ error: true, text: labels.baseSizeNameRequired });
        return;
      }
      const sizePrices = sizes.map((size) => ({
        id: size.id,
        priceMinor: parsePrice(size.price, digits),
        translations: size.translations,
      }));
      const input = {
        ...draft,
        priceMinor: sizePrices[0]?.priceMinor ?? parsePrice(price, digits),
        sizes: sizePrices,
      };
      const saved = item
        ? await client.save(item.id, savedVersion ?? item.version, input)
        : await client.create(input);
      setSavedVersion(saved.version);
      setFeedback({ error: false, text: labels.saved });
      onSaved(saved);
    } catch {
      setFeedback({ error: true, text: labels.error });
    } finally {
      lock.current = false;
      setPending(false);
    }
  }
  return (
    <section className={cn(page, className)}>
      <HostLink href={backHref} className={button}>
        {labels.back}
      </HostLink>
      <h1 className="text-2xl font-semibold">{item ? labels.editItem : labels.newItem}</h1>
      <form
        className="space-y-6"
        onSubmit={(event) => {
          event.preventDefault();
          void submit();
        }}
      >
        <div className="grid gap-4 sm:grid-cols-2">
          <label className="space-y-1">
            <span>{labels.category}</span>
            <select
              className={field}
              value={draft.categoryId}
              onChange={(event) => setDraft({ ...draft, categoryId: event.target.value })}
              required
            >
              {categories.map((category) => (
                <option key={category.id} value={category.id}>
                  {category.translations[baseLocale]}
                </option>
              ))}
            </select>
          </label>
          {sizes.length === 0 ? (
            <label className="space-y-1">
              <span>
                {labels.price} ({currency})
              </span>
              <input
                className={field}
                inputMode="decimal"
                value={price}
                onChange={(event) => setPrice(event.target.value)}
                required
              />
            </label>
          ) : null}
          <label className="space-y-1">
            <span>{labels.position}</span>
            <input
              className={field}
              type="number"
              min="0"
              step="1"
              value={draft.position}
              onChange={(event) => setDraft({ ...draft, position: Number(event.target.value) })}
              required
            />
          </label>
        </div>
        <Tabs.Root
          value={selectedLocale}
          onValueChange={(value) => setSelectedLocale(value as string)}
        >
          <Tabs.List
            aria-label={labels.language}
            className="flex gap-1 overflow-x-auto border-b border-border"
          >
            {editorLocales(locales, baseLocale).map((locale) => (
              <Tabs.Tab
                key={locale.code}
                type="button"
                value={locale.code}
                className="min-h-11 shrink-0 cursor-pointer border-b-2 border-transparent px-4 py-2 text-sm font-medium text-muted-foreground focus-visible:rounded-t-md focus-visible:outline-2 focus-visible:outline-ring disabled:cursor-not-allowed aria-disabled:cursor-not-allowed data-disabled:cursor-not-allowed data-[active]:border-primary data-[active]:text-foreground"
              >
                {locale.name}
              </Tabs.Tab>
            ))}
          </Tabs.List>
          {editorLocales(locales, baseLocale).map((locale) => {
            const translation = draft.translations[locale.code] ?? { name: "", description: "" };
            return (
              <Tabs.Panel key={locale.code} value={locale.code} className="space-y-4 pt-4">
                <label className="block space-y-1">
                  <span>
                    {labels.name}
                    {locale.code === baseLocale ? " *" : ""}
                  </span>
                  <input
                    className={field}
                    value={translation.name}
                    onChange={(event) =>
                      updateTranslation(locale.code, { name: event.target.value })
                    }
                    maxLength={200}
                    required={locale.code === baseLocale}
                  />
                </label>
                <label className="block space-y-1">
                  <span>{labels.description}</span>
                  <textarea
                    className={field}
                    rows={4}
                    value={translation.description}
                    onChange={(event) =>
                      updateTranslation(locale.code, { description: event.target.value })
                    }
                    maxLength={2000}
                  />
                </label>
              </Tabs.Panel>
            );
          })}
        </Tabs.Root>
        <fieldset className="min-w-0 space-y-3">
          <legend className="font-medium">{labels.sizes}</legend>
          <p className="text-sm text-muted-foreground">{labels.sizeHelp}</p>
          {sizes.map((size, index) => (
            <div key={size.id} className="flex items-end gap-2 rounded-xl border border-border p-3">
              <div className="grid min-w-0 flex-1 gap-3 sm:grid-cols-2">
                <label className="min-w-0 space-y-1">
                  <span>
                    {labels.sizeName} ({selectedLocale}) {index + 1}
                  </span>
                  <input
                    className={field}
                    value={size.translations[selectedLocale] ?? ""}
                    maxLength={120}
                    onChange={(event) =>
                      setSizes((current) =>
                        current.map((entry) =>
                          entry.id === size.id
                            ? {
                                ...entry,
                                translations: {
                                  ...entry.translations,
                                  [selectedLocale]: event.target.value,
                                },
                              }
                            : entry,
                        ),
                      )
                    }
                  />
                </label>
                <label className="min-w-0 space-y-1">
                  <span>
                    {labels.price} ({currency}) {index + 1}
                  </span>
                  <input
                    className={field}
                    inputMode="decimal"
                    value={size.price}
                    required
                    onChange={(event) =>
                      setSizes((current) =>
                        current.map((entry) =>
                          entry.id === size.id ? { ...entry, price: event.target.value } : entry,
                        ),
                      )
                    }
                  />
                </label>
              </div>
              <DeleteControl
                label={`${labels.removeSize}: ${size.translations[baseLocale] || index + 1}`}
                confirm={labels.confirmDelete}
                cancel={labels.cancel}
                errorMessage={labels.error}
                onDelete={async () => {}}
                onDone={() =>
                  setSizes((current) => current.filter((entry) => entry.id !== size.id))
                }
              />
            </div>
          ))}
          <button
            type="button"
            className={outlineButton}
            disabled={sizes.length >= 20}
            onClick={() =>
              setSizes((current) => [
                ...current,
                { id: crypto.randomUUID(), price, translations: { [baseLocale]: "" } },
              ])
            }
          >
            <PlusIcon aria-hidden="true" className="size-4 shrink-0" />
            {labels.addSize}
          </button>
        </fieldset>
        <fieldset className="space-y-2">
          <legend className="font-medium">{labels.spiceLevel}</legend>
          <div className="flex flex-wrap gap-2">
            {([0, 1, 2, 3] as const).map((level) => (
              <label
                key={level}
                className={cn(
                  "inline-flex min-h-11 max-w-full cursor-pointer items-center gap-2 rounded-xl border border-border px-3 py-2",
                  draft.spiceLevel === level && "ring-2 ring-ring",
                )}
              >
                <input
                  type="radio"
                  name="spiceLevel"
                  value={level}
                  checked={draft.spiceLevel === level}
                  className="size-4 shrink-0 cursor-pointer accent-primary focus-visible:ring-2 focus-visible:ring-ring"
                  onChange={() => setDraft((current) => ({ ...current, spiceLevel: level }))}
                />
                {level === 0 ? labels.notSpicy : <MenuSpiceBadge level={level} labels={labels} />}
              </label>
            ))}
          </div>
        </fieldset>
        <fieldset className="space-y-2">
          <legend className="font-medium">{labels.labels}</legend>
          <div className="flex flex-wrap gap-4">
            {labelsData.map((label) => (
              <label key={label.id} className="inline-flex items-center gap-2">
                <input
                  type="checkbox"
                  checked={draft.labelIds.includes(label.id)}
                  onChange={(event) =>
                    setDraft((current) => ({
                      ...current,
                      labelIds: event.target.checked
                        ? [...current.labelIds, label.id]
                        : current.labelIds.filter((id) => id !== label.id),
                    }))
                  }
                />
                <MenuLabelBadge
                  label={{ id: label.id, kind: label.kind, name: label.translations[baseLocale] }}
                />
              </label>
            ))}
          </div>
        </fieldset>
        <div className="flex flex-wrap gap-5">
          <label className="inline-flex items-center gap-2">
            <input
              type="checkbox"
              checked={draft.visible}
              onChange={(event) => setDraft({ ...draft, visible: event.target.checked })}
              disabled={!item}
            />
            {labels.visible}
          </label>
          <label className="inline-flex items-center gap-2">
            <input
              type="checkbox"
              checked={draft.soldOut}
              onChange={(event) => setDraft({ ...draft, soldOut: event.target.checked })}
            />
            {labels.unavailable}
          </label>
        </div>
        {draft.imageEntryId ? (
          <div className="flex items-center gap-3 text-sm">
            <span>
              {labels.photo}: {photoName || draft.imageEntryId}
            </span>
            <button
              type="button"
              className={button}
              onClick={() => setDraft({ ...draft, imageEntryId: null })}
            >
              {labels.removePhoto}
            </button>
          </div>
        ) : null}
        {feedback ? (
          <p
            role={feedback.error ? "alert" : "status"}
            className={feedback.error ? "text-destructive" : "text-muted-foreground"}
          >
            {feedback.text}
          </p>
        ) : null}
        <button type="submit" className={primary} disabled={pending || !categories.length}>
          {pending ? labels.saving : labels.save}
        </button>
      </form>
      {item && driveClient && getFolderHref ? (
        <div className="border-t border-border pt-6">
          <h2 className="mb-4 text-xl font-semibold">{labels.photo}</h2>
          <DriveBrowser
            client={driveClient}
            transferUpload={driveTransfer}
            scope={{ type: "menu-item", id: item.id }}
            parentId={photoFolderId}
            getFolderHref={getFolderHref}
            linkComponent={HostLink}
            onSelectFile={(entry) => {
              setDraft({ ...draft, imageEntryId: entry.id });
              setPhotoName(entry.name);
            }}
            isSelectableFile={(entry: DriveEntry) =>
              ["image/jpeg", "image/png", "image/webp"].includes(entry.contentType) &&
              entry.size <= 10_000_000
            }
            selectFileLabel={labels.selectPhoto}
            uploadAccept="image/jpeg,image/png,image/webp"
          />
        </div>
      ) : null}
    </section>
  );
}

export interface MenuTaxonomyPageProps {
  client: MenusClient;
  locales: readonly { code: string; name: string }[];
  baseLocale: string;
  backHref: string;
  linkComponent?: ComponentType<LinkProps>;
  labels?: Partial<MenusLabels>;
  className?: string;
}

function TaxonomyDialog({
  kind,
  existing,
  locales,
  baseLocale,
  labels,
  onSave,
}: {
  kind: "category" | "label";
  existing?: MenuCategory | MenuLabel;
  locales: readonly { code: string; name: string }[];
  baseLocale: string;
  labels: MenusLabels;
  onSave: (data: {
    id?: string;
    position: number;
    translations: Record<string, string>;
    kind?: MenuLabel["kind"];
  }) => Promise<void>;
}) {
  const [open, setOpen] = useState(false);
  const [pending, setPending] = useState(false);
  const [error, setError] = useState(false);
  const [position, setPosition] = useState(existing?.position ?? 0);
  const [translations, setTranslations] = useState<Record<string, string>>(
    existing?.translations ?? {},
  );
  const [labelKind, setLabelKind] = useState<MenuLabel["kind"]>(
    existing && "kind" in existing ? existing.kind : "allergen",
  );
  const title =
    kind === "category"
      ? existing
        ? labels.editCategory
        : labels.newCategory
      : existing
        ? labels.editLabel
        : labels.newLabel;
  return (
    <Dialog.Root open={open} onOpenChange={(value) => !pending && setOpen(value)}>
      <Dialog.Trigger className={existing ? iconButton : button} aria-label={title}>
        {existing ? (
          <PencilIcon aria-hidden="true" className="size-4 shrink-0" />
        ) : (
          <>
            <PlusIcon aria-hidden="true" className="size-4 shrink-0" />
            {title}
          </>
        )}
      </Dialog.Trigger>
      <Dialog.Portal>
        <Dialog.Backdrop className="fixed inset-0 z-50 bg-foreground/30" />
        <Dialog.Popup className="fixed top-1/2 left-1/2 z-50 max-h-[90vh] w-[min(30rem,calc(100vw-2rem))] -translate-x-1/2 -translate-y-1/2 overflow-y-auto rounded-2xl border border-border bg-popover p-6 text-popover-foreground shadow-xl">
          <Dialog.Title className="text-lg font-semibold">{title}</Dialog.Title>
          <form
            className="mt-5 space-y-4"
            onSubmit={(event) => {
              event.preventDefault();
              setPending(true);
              setError(false);
              void onSave({
                id: existing?.id,
                position,
                translations,
                ...(kind === "label" ? { kind: labelKind } : {}),
              })
                .then(() => setOpen(false))
                .catch(() => setError(true))
                .finally(() => setPending(false));
            }}
          >
            {editorLocales(locales, baseLocale).map((locale) => (
              <label key={locale.code} className="block space-y-1">
                <span>
                  {labels.name} ({locale.name}){locale.code === baseLocale ? " *" : ""}
                </span>
                <input
                  className={field}
                  value={translations[locale.code] ?? ""}
                  onChange={(event) =>
                    setTranslations({ ...translations, [locale.code]: event.target.value })
                  }
                  required={locale.code === baseLocale}
                  maxLength={120}
                />
              </label>
            ))}
            <label className="block space-y-1">
              <span>{labels.position}</span>
              <input
                className={field}
                type="number"
                min="0"
                step="1"
                value={position}
                onChange={(event) => setPosition(Number(event.target.value))}
                required
              />
            </label>
            {kind === "label" ? (
              <label className="block space-y-1">
                <span>{labels.labelKind}</span>
                <select
                  className={field}
                  value={labelKind}
                  onChange={(event) => setLabelKind(event.target.value as MenuLabel["kind"])}
                >
                  <option value="allergen">{labels.allergens}</option>
                  <option value="dietary">{labels.dietary}</option>
                </select>
              </label>
            ) : null}
            {error ? <ErrorMessage message={labels.error} /> : null}
            <div className="flex flex-wrap justify-end gap-2">
              <Dialog.Close className={outlineButton} disabled={pending}>
                {labels.cancel}
              </Dialog.Close>
              <button className={primary} disabled={pending}>
                {pending ? labels.saving : labels.save}
              </button>
            </div>
          </form>
        </Dialog.Popup>
      </Dialog.Portal>
    </Dialog.Root>
  );
}

export function MenuTaxonomyPage({
  client,
  locales,
  baseLocale,
  backHref,
  linkComponent: HostLink = Link,
  labels: overrides,
  className,
}: MenuTaxonomyPageProps) {
  const labels = { ...menusLabels, ...overrides };
  const [revision, setRevision] = useState(0);
  const [data, setData] = useState<{ categories: MenuCategory[]; labelsData: MenuLabel[] }>();
  const [error, setError] = useState(false);
  useEffect(() => {
    let active = true;
    Promise.all([client.categories(), client.labels()])
      .then(([categories, labelsData]) => {
        if (active) {
          setData({ categories, labelsData });
          setError(false);
        }
      })
      .catch(() => {
        if (active) setError(true);
      });
    return () => {
      active = false;
    };
  }, [client, revision]);
  const refresh = () => setRevision((n) => n + 1);
  return (
    <section className={cn(page, className)}>
      <HostLink href={backHref} className={button}>
        {labels.back}
      </HostLink>
      <h1 className="text-2xl font-semibold">
        {labels.categories} / {labels.labels}
      </h1>
      {error ? (
        <div>
          <ErrorMessage message={labels.error} />
          <button className={button} onClick={refresh}>
            <RefreshCwIcon className="size-4 shrink-0" aria-hidden="true" />
            {labels.retry}
          </button>
        </div>
      ) : null}
      {!data && !error ? <output>{labels.loading}</output> : null}
      {data ? (
        <>
          <section className="space-y-3">
            <div className="flex items-center justify-between">
              <h2 className="text-xl font-semibold">{labels.categories}</h2>
              <TaxonomyDialog
                key="new-category"
                kind="category"
                locales={locales}
                baseLocale={baseLocale}
                labels={labels}
                onSave={async (input) => {
                  await client.saveCategory({
                    position: input.position,
                    translations: input.translations,
                  });
                  refresh();
                }}
              />
            </div>
            <ul className="divide-y divide-border rounded-2xl border border-border">
              {data.categories.map((category) => (
                <li key={category.id} className="flex items-center justify-between p-3">
                  <span>{category.translations[baseLocale]}</span>
                  <div className="flex gap-2">
                    <TaxonomyDialog
                      key={category.id}
                      kind="category"
                      existing={category}
                      locales={locales}
                      baseLocale={baseLocale}
                      labels={labels}
                      onSave={async (input) => {
                        await client.saveCategory({
                          id: category.id,
                          position: input.position,
                          translations: input.translations,
                        });
                        refresh();
                      }}
                    />
                    <DeleteControl
                      label={`${labels.deleteCategory}: ${category.translations[baseLocale]}`}
                      confirm={labels.confirmDelete}
                      cancel={labels.cancel}
                      errorMessage={labels.error}
                      onDelete={() => client.removeCategory(category.id)}
                      onDone={refresh}
                    />
                  </div>
                </li>
              ))}
            </ul>
          </section>
          <section className="space-y-3">
            <div className="flex items-center justify-between">
              <h2 className="text-xl font-semibold">{labels.labels}</h2>
              <TaxonomyDialog
                key="new-label"
                kind="label"
                locales={locales}
                baseLocale={baseLocale}
                labels={labels}
                onSave={async (input) => {
                  await client.saveLabel({
                    kind: input.kind ?? "allergen",
                    position: input.position,
                    translations: input.translations,
                  });
                  refresh();
                }}
              />
            </div>
            <ul className="divide-y divide-border rounded-2xl border border-border">
              {data.labelsData.map((label) => (
                <li key={label.id} className="flex items-center justify-between p-3">
                  <span>
                    {label.translations[baseLocale]}{" "}
                    <span className="text-xs text-muted-foreground">({label.kind})</span>
                  </span>
                  <div className="flex gap-2">
                    <TaxonomyDialog
                      key={label.id}
                      kind="label"
                      existing={label}
                      locales={locales}
                      baseLocale={baseLocale}
                      labels={labels}
                      onSave={async (input) => {
                        await client.saveLabel({
                          id: label.id,
                          kind: input.kind ?? label.kind,
                          position: input.position,
                          translations: input.translations,
                        });
                        refresh();
                      }}
                    />
                    <DeleteControl
                      label={`${labels.deleteLabel}: ${label.translations[baseLocale]}`}
                      confirm={labels.confirmDelete}
                      cancel={labels.cancel}
                      errorMessage={labels.error}
                      onDelete={() => client.removeLabel(label.id)}
                      onDone={refresh}
                    />
                  </div>
                </li>
              ))}
            </ul>
          </section>
        </>
      ) : null}
    </section>
  );
}

import type { MenuLabel, MenuViewCategory, MenuViewLabel } from "@/components/plugins/menus/types";

export type MenuLabelTone = "success" | "pending" | "info";
export type MenuLabelIcon =
  | "leaf"
  | "vegan"
  | "fish"
  | "wheat"
  | "milk"
  | "egg"
  | "nut"
  | "bean"
  | "sprout"
  | "shrimp"
  | "shell"
  | "carrot"
  | "flower"
  | "seeds"
  | "wine"
  | "check";

export interface MenuLabelPreset extends MenuLabel {
  icon: MenuLabelIcon;
  tone: MenuLabelTone;
}

type Definition = [
  id: number,
  kind: MenuLabel["kind"],
  icon: MenuLabelIcon,
  tone: MenuLabelTone,
  en: string,
  fr: string,
  de: string,
  it: string,
];

// Allergen groups follow EFSA's list. Colors identify labels, not reaction severity.
const definitions: Definition[] = [
  [1, "dietary", "leaf", "success", "Vegetarian", "Végétarien", "Vegetarisch", "Vegetariano"],
  [2, "allergen", "milk", "info", "Milk", "Lait", "Milch", "Latte"],
  [3, "allergen", "wheat", "pending", "Gluten", "Gluten", "Gluten", "Glutine"],
  [4, "dietary", "vegan", "success", "Vegan", "Végétalien", "Vegan", "Vegano"],
  [5, "allergen", "shrimp", "info", "Crustaceans", "Crustacés", "Krebstiere", "Crostacei"],
  [6, "allergen", "egg", "info", "Eggs", "Œufs", "Eier", "Uova"],
  [7, "allergen", "fish", "info", "Fish", "Poisson", "Fisch", "Pesce"],
  [8, "allergen", "nut", "pending", "Peanuts", "Arachides", "Erdnüsse", "Arachidi"],
  [9, "allergen", "bean", "info", "Soy", "Soja", "Soja", "Soia"],
  [
    10,
    "allergen",
    "nut",
    "pending",
    "Tree nuts",
    "Fruits à coque",
    "Schalenfrüchte",
    "Frutta a guscio",
  ],
  [11, "allergen", "carrot", "info", "Celery", "Céleri", "Sellerie", "Sedano"],
  [12, "allergen", "flower", "info", "Mustard", "Moutarde", "Senf", "Senape"],
  [13, "allergen", "seeds", "info", "Sesame", "Sésame", "Sesam", "Sesamo"],
  [14, "allergen", "wine", "pending", "Sulphites", "Sulfites", "Sulfite", "Solfiti"],
  [15, "allergen", "sprout", "info", "Lupin", "Lupin", "Lupinen", "Lupini"],
  [16, "allergen", "shell", "info", "Molluscs", "Mollusques", "Weichtiere", "Molluschi"],
  [17, "dietary", "fish", "success", "Pescatarian", "Pescétarien", "Pescetarisch", "Pescetariano"],
  [26, "dietary", "check", "info", "Halal", "Halal", "Halal", "Halal"],
  [27, "dietary", "check", "info", "Kosher", "Casher", "Koscher", "Kosher"],
];

export const menuLabelPresets: readonly MenuLabelPreset[] = definitions.map(
  ([id, kind, icon, tone, en, fr, de, it], position) => ({
    id: `20000000-0000-4000-8000-${String(id).padStart(12, "0")}`,
    kind,
    icon,
    tone,
    position,
    translations: { en, fr, de, it },
  }),
);

const normalize = (name: string) =>
  name.normalize("NFKD").replace(/\p{M}/gu, "").trim().toLowerCase();
const aliases: Record<string, readonly string[]> = {
  milk: ["Dairy", "Produits laitiers"],
  gluten: ["Cereals containing gluten", "Céréales contenant du gluten"],
  eggs: ["Egg", "Oeufs"],
  soy: ["Soybeans", "Soya"],
  "tree nuts": ["Nuts", "Noix"],
  sulphites: ["Sulfites", "Sulphur dioxide", "Sulfur dioxide", "Dioxyde de soufre"],
  vegan: ["Vegan", "Végane"],
};

export function getMenuLabelPreset(label: MenuViewLabel) {
  return (
    menuLabelPresets.find((preset) => preset.kind === label.kind && preset.id === label.id) ??
    menuLabelPresets.find(
      (preset) =>
        preset.kind === label.kind &&
        [
          ...Object.values(preset.translations),
          ...(aliases[preset.translations.en.toLowerCase()] ?? []),
        ].some((name) => normalize(name) === normalize(label.name)),
    )
  );
}

export function getMenuFilterLabels(
  sections: readonly MenuViewCategory[],
  locale: string,
  filterLabels?: readonly MenuViewLabel[],
): MenuViewLabel[] {
  const used = [
    ...new Map(
      sections
        .flatMap((section) =>
          section.items.filter((item) => item.visible).flatMap((item) => item.labels),
        )
        .map((label) => [label.id, label]),
    ).values(),
  ];
  const defaults =
    filterLabels ??
    menuLabelPresets.map((preset) => ({
      id: preset.id,
      kind: preset.kind,
      name:
        preset.translations[locale] ??
        preset.translations[locale.split("-")[0]] ??
        preset.translations.en,
    }));
  const options = defaults
    .map(
      (label) =>
        used.find(
          (item) =>
            item.id === label.id ||
            (getMenuLabelPreset(item)?.id ?? item.id) ===
              (getMenuLabelPreset(label)?.id ?? label.id),
        ) ?? label,
    )
    .filter((label) => used.some((item) => item.id === label.id));
  const ids = new Set(options.map((label) => label.id));
  const collator = new Intl.Collator(locale, { sensitivity: "base" });
  return [...options, ...used.filter((label) => !ids.has(label.id))].sort(
    (a, b) => collator.compare(a.name, b.name) || a.id.localeCompare(b.id),
  );
}

import {
  BadgeCheckIcon,
  BeanIcon,
  CarrotIcon,
  CircleDotIcon,
  EggIcon,
  FishIcon,
  Flower2Icon,
  LeafIcon,
  MilkIcon,
  NutIcon,
  ShellIcon,
  ShrimpIcon,
  SproutIcon,
  TriangleAlertIcon,
  VeganIcon,
  WheatIcon,
  WineIcon,
} from "lucide-react";

import {
  getMenuLabelPreset,
  type MenuLabelIcon,
  type MenuLabelTone,
} from "@/components/plugins/menus/label-presets";
import type { MenuViewLabel } from "@/components/plugins/menus/types";
import { cn } from "@/components/utils/cn";

const icons: Record<MenuLabelIcon, typeof LeafIcon> = {
  leaf: LeafIcon,
  vegan: VeganIcon,
  fish: FishIcon,
  wheat: WheatIcon,
  milk: MilkIcon,
  egg: EggIcon,
  nut: NutIcon,
  bean: BeanIcon,
  sprout: SproutIcon,
  shrimp: ShrimpIcon,
  shell: ShellIcon,
  carrot: CarrotIcon,
  flower: Flower2Icon,
  seeds: CircleDotIcon,
  wine: WineIcon,
  check: BadgeCheckIcon,
};
const tones: Record<MenuLabelTone, string> = {
  success: "bg-status-success text-status-success-foreground",
  pending: "bg-status-pending text-status-pending-foreground",
  info: "bg-status-info text-status-info-foreground",
};

export function menuLabelColorClasses(label: MenuViewLabel) {
  return tones[getMenuLabelPreset(label)?.tone ?? (label.kind === "dietary" ? "success" : "info")];
}

export interface MenuLabelBadgeProps {
  label: MenuViewLabel;
  className?: string;
}

export function MenuLabelBadge({ label, className }: MenuLabelBadgeProps) {
  const preset = getMenuLabelPreset(label);
  const Icon = preset
    ? icons[preset.icon]
    : label.kind === "dietary"
      ? LeafIcon
      : TriangleAlertIcon;
  return (
    <span
      className={cn(
        "inline-flex max-w-full items-center gap-1.5 rounded-full px-2.5 py-1 text-xs font-medium",
        menuLabelColorClasses(label),
        className,
      )}
    >
      <Icon aria-hidden="true" className="size-4 shrink-0" />
      <span className="min-w-0 wrap-anywhere">{label.name}</span>
    </span>
  );
}

import { FlameIcon } from "lucide-react";

import { menusLabels, type MenusLabels } from "@/components/plugins/menus/labels";
import type { MenuSpiceLevel } from "@/components/plugins/menus/types";
import { cn } from "@/components/utils/cn";

export interface MenuSpiceBadgeProps {
  level: MenuSpiceLevel;
  labels?: Partial<MenusLabels>;
  className?: string;
}

export function MenuSpiceBadge({ level, labels: overrides, className }: MenuSpiceBadgeProps) {
  if (level === 0) return null;
  const labels = { ...menusLabels, ...overrides };
  const text = level === 1 ? labels.mildSpice : level === 2 ? labels.mediumSpice : labels.hotSpice;
  return (
    <span
      className={cn(
        "inline-flex max-w-full items-center gap-1.5 rounded-full bg-status-pending px-2.5 py-1 text-xs font-medium text-status-pending-foreground",
        className,
      )}
    >
      <span className="inline-flex shrink-0 gap-0.5" aria-hidden="true">
        {Array.from({ length: level }, (_, index) => (
          <FlameIcon key={index} className="size-4" aria-hidden="true" />
        ))}
      </span>
      <span className="min-w-0 wrap-anywhere">{text}</span>
    </span>
  );
}
